    });

    test('not mergeable (CONFLICTING/DIRTY) -> flagged skip', function () {
        var fx = fixture({
            labeledIssues: [3],
            prs: [{ number: 10, body: 'Closes #3', headRefName: 'x' }],
            prStates: { 10: { mergeable: false, state: 'DIRTY' } }
