            labeledIssues: [7],
            prs: [{ number: 21, body: 'Slice one.\n\nPart of #7', headRefName: 'feat/slice' }]
        });
        var result = run(fx);
        assert.equal(result.merged, 1, 'Part-of linked PR merges for the labeled issue');
