        // Build TC list for AI
        var totalHistoricalDoneBugs = 0;
        var tcList = failedTCs.map(function(tc) {
            var fields = tc.fields || {};
            var comments = fields.comment && fields.comment.comments;
            var lastComment = comments && comments.length > 0
