        });

        file_write(inputFolder + '/failed_tcs.json', JSON.stringify(tcList, null, 2));
        console.log('Wrote input/failed_tcs.json with ' + tcList.length + ' TCs');

        // Fetch non-Done bugs
        console.log('Fetching non-Done bugs with JQL:', openBugsJql);
