/**
 * Prepare Bulk Bugs Creation Context (preCliJSAction for bulk_bugs_creation agent)
 *
 * Fetches all failed Test Cases (without sm_bug_creation_triggered label) and
 * all non-Done bugs, then writes them to input files for the AI to process in batch.
 *
 * Writes:
 *   input/failed_tcs.json  — array of failed TC objects
 *   input/open_bugs.json   — array of non-Done bug objects
 *   input/context.md       — summary for the AI
 *
 * The SM passes one ticket as the "trigger" but this action ignores it and
 * fetches ALL eligible failed TCs up to batchSize.
 */

var configLoader = require('./configLoader.js');
const { JIRA_FIELDS } = require('./config.js');
var trackersModule = require('./common/trackers.js');

function summarizeDoneBug(bug) {
    var fields = bug.fields || {};
    return {
        key: bug.key,
        summary: fields.summary || '',
        status: fields.status ? fields.status.name : '',
        updated: fields.updated || '',
        description: (fields.description || '').substring(0, 500)
    };
}

function getFailedReasonFieldName(config, customParams) {
    return (customParams && customParams.failedReasonField)
        || (config && config.jira && config.jira.fields && config.jira.fields.failedReason)
        || JIRA_FIELDS.FAILED_REASON
        || 'Failed Reason';
}

function extractFailedReason(fields, fieldName) {
    if (!fields || !fieldName) return '';
    var raw = fields[fieldName];
    if (typeof raw === 'string') return raw;
    if (raw && typeof raw.value === 'string') return raw.value;
    // Fallback: dmtools may transform customfield_12345 into "Name (customfield_12345)".
    if (fieldName.indexOf('customfield_') !== -1) {
        for (var key in fields) {
            if (fields.hasOwnProperty(key) && key.indexOf(fieldName) !== -1) {
                var v = fields[key];
                if (typeof v === 'string') return v;
                if (v && typeof v.value === 'string') return v.value;
            }
        }
    }
    return '';
}

function extractAttachmentNames(fields) {
    var attachments = fields && fields.attachment;
    if (!Array.isArray(attachments)) return [];
    return attachments.map(function(a) { return a.filename || ''; }).filter(function(n) { return n; });
}

function fetchHistoricalDoneBugs(tcKey, tracker) {
    try {
        tracker = tracker || trackersModule.createTracker(null, {});
        // JQL text: provider-specific query (WIQL on ado)
        var bugs = tracker.searchIssues('issue in linkedIssues("' + tcKey + '") AND issuetype = Bug AND status in (Done) ORDER BY updated DESC', {
            fields: ['key', 'summary', 'description', 'status', 'updated'],
            maxResults: 10
        }) || [];
        return bugs.map(summarizeDoneBug);
    } catch (e) {
        console.warn('Failed to fetch historical Done bugs for ' + tcKey + ':', e);
        return [];
    }
}

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var inputFolder = actualParams.inputFolderPath;

        var customParams = actualParams.customParams || {};
        var projectKey = (actualParams.jira && actualParams.jira.project)
            || (params.ticket && params.ticket.key && params.ticket.key.split('-')[0])
            || 'TS';
        var batchSize = customParams.batchSize || 50;

        var config = configLoader.loadProjectConfig(actualParams);
        // agents#855: {jiraProject} is replaced with the project key derived above; {status.KEY:Literal}
        // follows jira.statuses only when the project opted in (jira.useConfiguredStatusesInQueries),
        // otherwise it stays the literal — the default queries are byte-identical to the previous ones.
        var statusConfig = { jira: { statuses: (config.jira && config.jira.statuses) || {},
            useConfiguredStatusesInQueries: !!(config.jira && config.jira.useConfiguredStatusesInQueries),
            project: projectKey, parentTicket: '' } };
        var openBugsJql = configLoader.interpolateJql(
            customParams.openBugsJql || 'project = {jiraProject} AND issuetype in (Bug) AND status not in ({status.DONE:Done})',
            statusConfig);

        var failedTCsJql = configLoader.interpolateJql(customParams.failedTCsJql ||
            // gh-916: {stage.*} — in label mode a TC carrying the stage_failed marker is selectable too;
            // in 'none' mode this expands to the same `status in ('Failed')` clause as before.
            'project = {jiraProject} AND issuetype = "Test Case" AND {stage.FAILED:Failed} AND (labels is EMPTY OR labels NOT IN (sm_bug_creation_triggered)) ORDER BY created ASC',
            statusConfig);

        var tracker = trackersModule.createTracker(config, customParams);
        var failedReasonFieldName = getFailedReasonFieldName(config, customParams);
        console.log('Failed Reason field name:', failedReasonFieldName);

        console.log('=== Preparing bulk bugs creation context ===');
        console.log('Project:', projectKey, '| batchSize:', batchSize);

        // Fetch failed TCs
        console.log('Fetching failed TCs with JQL:', failedTCsJql);
        var failedTCs = [];
        try {
            var tcFields = ['key', 'summary', 'description', 'comment', 'status', 'labels', 'parent', 'attachment'];
            if (failedReasonFieldName && failedReasonFieldName.indexOf('customfield_') !== -1) {
                tcFields.push(failedReasonFieldName);
            }
            var tcResults = tracker.searchIssues(failedTCsJql, {
                fields: tcFields,
                maxResults: batchSize
            });
            failedTCs = tcResults || [];
        } catch (e) {
            console.error('Failed to fetch failed TCs:', e);
        }

        console.log('Found ' + failedTCs.length + ' failed TC(s) to process');

        if (failedTCs.length === 0) {
            file_write(inputFolder + '/no_failed_tcs.md', 'No failed Test Cases to process. Exiting.');
            console.log('No failed TCs — wrote no_failed_tcs.md');
            return;
        }

        // Build TC list for AI
        var totalHistoricalDoneBugs = 0;
        var tcList = failedTCs.map(function(tc) {
            var fields = tc.fields || {};
            var comments = fields.comment && fields.comment.comments;
            var lastComment = comments && comments.length > 0
                ? comments[comments.length - 1].body
                : '';
            var historicalDoneBugs = fetchHistoricalDoneBugs(tc.key, tracker);
            totalHistoricalDoneBugs += historicalDoneBugs.length;
            return {
                key: tc.key,
                summary: fields.summary || '',
                description: fields.description || '',
                failedReason: extractFailedReason(fields, failedReasonFieldName),
                attachmentNames: extractAttachmentNames(fields),
                lastComment: lastComment,
                parent: fields.parent ? fields.parent.key + ' — ' + (fields.parent.fields && fields.parent.fields.summary || '') : '',
                historicalDoneBugs: historicalDoneBugs
            };
        });

        file_write(inputFolder + '/failed_tcs.json', JSON.stringify(tcList, null, 2));
        console.log('Wrote input/failed_tcs.json with ' + tcList.length + ' TCs');

        // Fetch non-Done bugs
        console.log('Fetching non-Done bugs with JQL:', openBugsJql);
        var bugs = [];
        try {
            var bugResults = tracker.searchIssues(openBugsJql, {
                fields: ['key', 'summary', 'description', 'status', 'priority'],
                maxResults: 300
            });
            bugs = bugResults || [];
        } catch (e) {
            console.error('Failed to fetch open bugs:', e);
        }

        console.log('Found ' + bugs.length + ' non-Done bug(s)');

        var bugList = bugs.map(function(bug) {
            var fields = bug.fields || {};
            return {
                key: bug.key,
                summary: fields.summary || '',
                description: (fields.description || '').substring(0, 500),
                status: fields.status…

/**
 * mergeTrigger — the canonical pr_approved merge sweep (JSRunner).
 *
 * Port of the inline bash in
 * IstiN/dmtools-agentic-workflows/.github/workflows/factory-merge-trigger.yml
 * (main, incl. the awf#20 Part-of + orphan-carrier path and the awf#21
 * numeric guards — replicated as semantics; the structured JSON bridge
 * makes the tab/newline body sanitizing unnecessary).
 *
 *   issue labeled `pr_approved` → linked open PR found → mergeStateStatus
 *   CLEAN → squash-merge → labels removed → comment posted.
 *
 * Linking conventions (any of):
 *   - PR body contains `Closes #NN` / `Fixes #NN` / `Resolves #NN`
 *   - PR body contains `Part of #NN` (link WITHOUT close)
 *   - PR branch name starts with `NN-` (e.g. `42-fix-foo`)
 *   - PR branch name matches `gh-0*NN` (gated by jobParams.ghBranchPattern
 *     on the issue→PR scan; the PR→issue map-back keeps it unconditional,
 *     bash parity)
 *   - the PR itself carries the label — mapped back to its linked issue;
 *     a labeled PR with NO OPEN linked issue merges directly (orphan /
 *     PR-carrier path: fix/*, chore/*, machine PRs)
 *
 * Error isolation: every per-item github_* call failure is caught, counted
 * in `failed`, and the loop continues; after BOTH loops a nonzero `failed`
 * count throws so the JSRunner surfaces the run as a job failure (bash had
 * no such aggregate — `set -e` simply killed the run mid-loop).
 *
 * jsrunner contract: params arrive via params.jobParams:
 *   repo            "owner/name" (required; GH_REPO fallback)
 *   label           approval label (default 'pr_approved')
 *   mapPrLabels     map labeled PRs back to their issues (default true)
 *   ghBranchPattern also link issue→PR via branch names like gh-0*NN
 *                   (default true)
 *   removePrLabel   also remove the label from the merged PR (default true)
 *   ciRunUrl        CI run URL stamped into the merge comments
 */

/* global github_search_issues, github_get_issue, github_list_prs,
   github_get_pr, github_merge_pr, github_remove_label,
   github_create_comment, GH_REPO */

function parseMcp(raw) {
    if (raw === null || raw === undefined) return {};
    if (typeof raw === 'object') return raw;
    try { return JSON.parse(String(raw)); } catch (e) { return {}; }
}

function asList(parsed) {
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.items)) return parsed.items;
    if (parsed && Array.isArray(parsed.pullRequests)) return parsed.pullRequests;
    return [];
}

function asBool(value, dflt) {
    if (value === undefined || value === null || value === '') return dflt;
    if (value === true || value === false) return value;
    return String(value).toLowerCase() !== 'false';
}

function labelNames(pr) {
    return (pr.labels || []).map(function (l) { return (l && l.name) || l; });
}

function hasLabel(pr, label) {
    return labelNames(pr).indexOf(label) !== -1;
}

function branchOf(pr) {
    return pr.headRefName || (pr.head && pr.head.ref) || '';
}

function bodyOf(pr) {
    return typeof pr.body === 'string' ? pr.body : '';
}

function escapeRegExp(s) {
    return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Extract a linked issue number from a PR's body/branch (PR→issue
 * map-back, bash parity):
 *   1. body: first `closes|fixes|resolves|part of #NN` (case-insensitive)
 *   2. branch: leading digits (`NN-…` — bash uses `^[0-9]+`, no separator
 *      required)
 *   3. branch: `gh-0*NN` anywhere — UNCONDITIONAL here (the bash map-back
 *      ignores GH_BRANCH_PATTERN; only the issue→PR selector is gated).
 */
function extractLinkedIssueNumber(pr) {
    var m = bodyOf(pr).match(/\b(?:closes|fixes|resolves|part of)\s+#(\d+)/i);
    if (m) return parseInt(m[1], 10);
    m = branchOf(pr).match(/^(\d+)/);
    if (m) return parseInt(m[1], 10);
    m = branchOf(pr).match(/gh-0*(\d+)/i);
    if (m) return parseInt(m[1], 10);
    return null;
}

/**
 * Does this open PR link to issue `n`? (issue→PR selector, bash jq
 * link_sel parity: body keyword ref, branch `^N[-_.]`, and — gated by
 * ghBranchPattern — a trailing `(^|[-_./])gh-0*N$`.)
 */
function prLinksToIssue(pr, n, ghBranchPattern) {
    var body = bodyOf(pr);
    var branch = branchOf(pr);
    var bodyRe = new RegExp('\\b(?:closes|fixes|resolves|part of)\\s+#' + n + '\\b', 'i');
    if (bodyRe.test(body)) return true;
    var branchRe = new RegExp('^' + n + '[-_.]');
    if (branchRe.test(branch)) return true;
    if (ghBranchPattern) {
        var ghRe = new RegExp('(^|[-_./])gh-0*' + n + '$', 'i');
        if (ghRe.test(branch)) return true;
    }
    return false;
}

/**
 * Is the linked issue OPEN? The sync github_get_issue bridge does not
 * throw on 404 — it returns the REST error body ({"message":"Not Found"})
 * — so both a throw and a message-carrying body count as absent (→ the PR
 * takes the orphan-carrier path).
 */
function isIssueOpen(owner, name, n) {
    var res;
    try {
        res = parseMcp(github_get_issue({
            workspace: owner, repository: name, number: n
        }));
    } catch (e) {
        return false; // throwing bridges (mocks, some forges) — 404 throws
    }
    if (!res || res.message) return false;
    return String(res.state || '').toUpperCase() === 'OPEN';
}

/**
 * Mergeability, gh CLI parity: bash reads `.mergeable + ":" +
 * .mergeStateStatus` where mergeable is MERGEABLE|CONFLICTING|UNKNOWN.
 * REST carries mergeable true/false/null + mergeable_state lowercase.
 */
function mergeStateOf(pr) {
    var mergeable = pr.mergeable === true ||
        String(pr.mergeable).toUpperCase() === 'MERGEABLE';
    var state = pr.mergeStateStatus ||
        (pr.mergeable_state ? String(pr.mergeable_state).toUpperCase() : '');
    return { mergeable: mergeable, state: state };
}

function squashMerge(owner, name, number) {
    try {
        var res = parseMcp(github_merge_pr({
            workspace: owner, repository: name,
            pullRequestId: number, mergeMethod: 'squash'
        }));
        if (res.merged === true || res.ok === true) return { merged: true };
        return { merged: false, error: res.message || JSON.stringify(res) };
    } catch (e) {
        return { merged: false, error: (e && e.message) || String(e) };
    }
}

function tryRemoveLabel(owner, name, number, label, log) {
    try {
        github_remove_label({
            workspace: owner, repository: name, number: number, label: label
        });
    } catch (e) {
        log.push('⚠️ label removal failed on #' + number + ' (non-fatal): ' +
            ((e && e.message) || e));
    }
}

function tryComment(owner, name, number, body, log) {
    try {
        github_create_comment({
            workspace: owner, repository: name, number: number, body: body
        });
    } catch (e) {
        log.push('⚠️ comment failed on #' + number + ' (non-fatal): ' +
            ((e && e.message) || e));
    }
}

/**
 * The shared state machine (bash `case "$state"` parity). Returns
 * 'merged' | 'skipped'. `onMerged(mergedPrNumber)` performs the
 * post-merge label/comment bookkeeping for the caller's path.
 */
function runStateMachine(ctx, prNumber, onMerged) {
    var pr = parseMcp(github_get_pr({
        workspace: ctx.owner, repository: ctx.name, pullRequestId: prNumber
    }));
    var ms = mergeStateOf(pr);
    var stateLabel = (ms.mergeable ? 'MERGEABLE' : 'CONFLICTING') + ':' + ms.state;
    ctx.log.push('linked PR #' + prNumber + ' — ' + stateLabel);

    if (ms.mergeable && ms.state === 'CLEAN') {
        var res = squashMerge(ctx.owner, ctx.name, prNumber);
        if (res.merged) {
            onMerged(prNumber);
            return 'merged';
        }
        ctx.log.push('❌ merge of #' + prNumber + ' failed: ' + res.error);
        return 'skipped'; // bash parity: a refused merge is skipped, exit 0
    }
    if (ms.mergeable && ms.state === 'BEHIND') {
        ctx.log.push('⏳ #' + prNumber + ' behind main — the SM (silent-update-behind) refreshes it, then re-dispatches CI');
        return 'skipped';
    }
    if (ms.mergeable && (ms.state === 'BLOCKED' || ms.state === 'UNSTABLE')) {
        ctx.log.push('⏳ #' + prNumber + ' required checks not g…

