    });

    test("default ciRunUrl 'run' is stamped into the merge comment", function () {
        var fx = fixture({
            labeledIssues: [5],
            prs: [{ number: 12, body: 'Closes #5', headRefName: 'x' }]
        });
        run(fx);
        assert.ok(fx.calls.comments[0].body.indexOf('(CI: run)') !== -1,
            fx.calls.comments[0].body);
    });
});

