        var prn = parseInt(pr.number, 10);
        try {
            var n = extractLinkedIssueNumber(pr);
            if (n !== null && isIssueOpen(owner, name, n)) {
                if (!seenIssues[n]) {
                    seenIssues[n] = true;
                    issueNumbers.push(n);
                }
            } else {
                // No resolvable issue, or the issue is closed/absent
                // (awf#20) — the PR itself is the carrier.
                orphanPrs.push(prn);
            }
