            '🔀 Merged (CI: ' + opts.ciRunUrl + ')', ctx.log);
        ctx.say('✅ merged PR #' + mergedPr + ' (issue-less)');
    });
    if (outcome === 'merged') tally.merged++; else tally.skipped++;
}

