        ctx.log.push('⏳ #' + prNumber + ' required checks not green yet');
        return 'skipped';
    }
    ctx.log.push('⛔ #' + prNumber + ' not mergeable (' + stateLabel + ') — needs manual attention');
    return 'skipped';
}

