+function action(params) {
+    var job = (params && params.jobParams) || {};
+    var repoInfo = resolveRepo(job);
+    var owner = repoInfo.owner;
+    var name = repoInfo.name;
+    var opts = parseFlags(job);
+
+    var log = [];
