+        return { success: true, merged: 0, skipped: 0, failed: 0, log: log };
+    }
+
+    var tally = { merged: 0, skipped: 0, failed: 0 };
+    runSweep(ctx, candidates, opts, tally);
+    return summarizeSweep(tally, log, say);
