+function collectCandidates(owner, name, opts, ctx) {
+    var issueSearch = parseMcp(github_search_issues({
+        workspace: owner, repository: name,
+        query: 'repo:' + owner + '/' + name + ' is:issue is:open label:"' + opts.label + '"'
+    }));
