187:/**
188: * The shared state machine (bash `case "$state"` parity). Returns
189: * 'merged' | 'skipped'. `onMerged(mergedPrNumber)` performs the
190: * post-merge label/comment bookkeeping for the caller's path.
191: */
192:function runStateMachine(ctx, prNumber, onMerged) {
193:    var pr = parseMcp(github_get_pr({
194:        workspace: ctx.owner, repository: ctx.name, pullRequestId: prNumber
195:    }));
196:    var ms = mergeStateOf(pr);
197:    var stateLabel = (ms.mergeable ? 'MERGEABLE' : 'CONFLICTING') + ':' + ms.state;
198:    ctx.log.push('linked PR #' + prNumber + ' — ' + stateLabel);
199:
200:    if (ms.mergeable && ms.state === 'CLEAN') {
201:        var res = squashMerge(ctx.owner, ctx.name, prNumber);
202:        if (res.merged) {
203:            onMerged(prNumber);
204:            return 'merged';
205:        }
206:        ctx.log.push('❌ merge of #' + prNumber + ' failed: ' + res.error);
207:        return 'skipped'; // bash parity: a refused merge is skipped, exit 0
208:    }
209:    if (ms.mergeable && ms.state === 'BEHIND') {
210:        ctx.log.push('⏳ #' + prNumber + ' behind main — the SM (silent-update-behind) refreshes it, then re-dispatches CI');
211:        return 'skipped';
212:    }
213:    if (ms.mergeable && (ms.state === 'BLOCKED' || ms.state === 'UNSTABLE')) {
214:        ctx.log.push('⏳ #' + prNumber + ' required checks not green yet');
215:        return 'skipped';
